import { useTheme } from '@emotion/react';
import * as React from 'react';

import { Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';

import { pxToRem } from 'util/util';
import { triggerHaptic } from "tactus";
import ButtonWithHaptic from './ButtonWithHaptic';

const MainButton = (props) => {
    const theme = useTheme();
    const { buttonP, typoP, isFlag, children } = props;
	const { onClick, ...restButtonP } = buttonP;

    return (
        <ButtonWithHaptic
            color="primary"
            variant={isFlag ? 'outlined' : 'contained'}
            onClick={() => {
                onClick();
                triggerHaptic();
            }}
            {...restButtonP}
            sx={{
                ...buttonP?.sx,
                'svg.MuiSvgIcon-root': {
                    filter: `drop-shadow(2px 2px 0px ${alpha(theme.palette.shadow, 0.2)})`,
                },
            }}>
            {isFlag ? (
                <>{children}</>
            ) : (
                <Typography
                    component="span"
                    fontSize={pxToRem(24)}
                    fontWeight="800"
                    {...typoP}
                    sx={{
                        textShadow: `2px 2px 0px ${alpha(theme.palette.shadow, 0.2)}`,
                    }}>
                    {children}
                </Typography>
            )}
        </ButtonWithHaptic>
    );
};

export default MainButton;
