import { triggerHaptic } from "tactus";
import { Button } from '@mui/material';

const ButtonWithHaptic = (props) => {
	const {onClick, children, ...restProps} = props;
	return <Button
	 onClick={() => {triggerHaptic(); props.onClick()}}
	 {...restProps}
	>{children}</Button>
};

export default ButtonWithHaptic;