import { QuestionType } from 'store/quizBuilder/questionTypes/QuestionType';

export class QuestionTypeUniqueFact extends QuestionType {
    getQuestion(_entity) {
        const oneUniqueFact = _entity.getValue(this.language, 'uniqueFacts');

        const questionText = oneUniqueFact[this.language];
        let allAnswers = this.getAnswer(_entity);
        const choices = this.getChoices(_entity, allAnswers, this.getChoicesList());
        let answer;
        if (Array.isArray(allAnswers)) {
            answer = allAnswers.pop();
        } else {
            answer = allAnswers;
        }
        const answerAdditionnalText = oneUniqueFact.additionnal;
        const questionPhraseValues = this.getQuestionPhraseValues(_entity);
        return { questionText, answer, choices, answerAdditionnalText, questionPhraseValues };
    }
}
